import java.io.*
import java.util.*

const val MD = 998244353

fun main() {
    val `in` = FastScanner()
    val out = PrintWriter(System.out)

    val n = `in`.nextInt()
    val k_ = `in`.nextLong()

    if (k_ >= n) {
        out.println(0)
        out.flush()
        return
    }

    val c = n - k_.toInt()
    val size = n + n
    val ff = IntArray(size)
    val gg = IntArray(size)

    var f = 1
    for (i in 0 until size) {
        ff[i] = f
        gg[i] = modPow(f, MD - 2).toInt()
        f = (f.toLong() * (i + 1) % MD).toInt()
    }

    fun ch(n: Int, k: Int): Long {
        if (k < 0 || k > n) return 0
        return ff[n].toLong() * gg[k] % MD * gg[n - k] % MD
    }

    var ans = 0L
    for (a in 1..c) {
        val x = modPow(a, n) * ch(c, a) % MD
        if ((c - a) % 2 == 0) {
            ans += x
        } else {
            ans -= x
        }
    }

    ans %= MD
    if (ans < 0) ans += MD
    ans = ans * ch(n, c) % MD
    if (k_ > 0) ans = ans * 2 % MD

    out.println(ans)
    out.flush()
}

fun modPow(a: Int, e: Int): Long {
    var base = a.toLong()
    var exp = e
    var res = 1L
    while (exp > 0) {
        if (exp and 1 == 1) res = res * base % MD
        base = base * base % MD
        exp = exp shr 1
    }
    return res
}

class FastScanner(private val `in`: InputStream = System.`in`) {
    private val buffer = ByteArray(1 << 16)
    private var ptr = 0
    private var len = 0

    private fun read(): Int {
        if (ptr >= len) {
            len = `in`.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextInt(): Int {
        var c = read()
        while (c <= ' ') c = read()
        var neg = false
        if (c == '-') {
            neg = true
            c = read()
        }
        var x = 0
        while (c > ' ') {
            x = x * 10 + (c - '0')
            c = read()
        }
        return if (neg) -x else x
    }

    fun nextLong(): Long {
        var c = read()
        while (c <= ' ') c = read()
        var neg = false
        if (c == '-') {
            neg = true
            c = read()
        }
        var x = 0L
        while (c > ' ') {
            x = x * 10 + (c - '0')
            c = read()
        }
        return if (neg) -x else x
    }
}

